import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/opt/tools');import rcb_dtb
s=rcb_dtb.Session('/app/instance.json');M,D=s.model,s.data;jq=s._jq;palm=M.body('palmworld').id
q0=D.qpos[jq].copy();p0=D.xpos[palm].copy();R0=D.xmat[palm].reshape(3,3).copy()
def ik(pos,Rtar,qseed=None):
 q=q0[:7].copy() if qseed is None else qseed.copy()
 for it in range(200):
  D.qpos[jq[:7]]=q;D.qvel[:]=0;mujoco.mj_forward(M,D);p=D.xpos[palm].copy();R=D.xmat[palm].reshape(3,3).copy();ep=pos-p;er=(Rotation.from_matrix(Rtar)*Rotation.from_matrix(R).inv()).as_rotvec()
  if np.linalg.norm(ep)<.0005 and np.linalg.norm(er)<.005:break
  jp=np.zeros((3,M.nv));jr=np.zeros((3,M.nv));mujoco.mj_jacBody(M,D,jp,jr,palm);J=np.vstack([jp[:,:7],jr[:,:7]]);dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.0025,np.r_[ep,er]);q=np.clip(q+np.clip(dq,-.08,.08),s.lower[:7],s.upper[:7])
 return q
# let object settle
for _ in range(50):s.step(s.targets)
p0=D.xpos[palm].copy();R0=D.xmat[palm].reshape(3,3).copy();home=s.targets.copy()
# move above far side, fingers open
p_far=p0+np.array([0,.053,-.091]);qf=ik(p_far,R0,home[:7]);A=home.copy();A[:7]=qf
for k in range(100):s.step(home+(A-home)*(k+1)/100)
print('far open',np.round(s.state()['palm_pos'],3),np.round(s.state()['object_pos'],3))
# curl fingers while safely outside the object
G=np.zeros(22);G[5:9]=[1.571,.132,.72,.482];G[9:13]=[1.571,.349,.689,.328];G[13:17]=[1.571,.349,.609,.057];G[17:22]=[.26,1.571,.349,.602,.717]
C=A.copy();C[7:]=G
for k in range(120):s.step(A+(C-A)*(k+1)/120)
print('curled far',np.round(s.state()['palm_pos'],3),np.round(s.state()['object_pos'],3))
for n in ['index_DP','middle_DP','ring_DP','pinky_DP']:print(n,np.round(D.xpos[M.body('palmleft_'+n).id],3))
# translate closed fingers under pad from y+ side to center y
p_under=p0+np.array([0,-.070,-.091]);qu=ik(p_under,R0,qf);U=C.copy();U[:7]=qu
for k in range(120):
 s.step(C+(U-C)*(k+1)/120)
 if (k+1)%30==0:print('slide',k+1,'palm',np.round(s.state()['palm_pos'],3),'obj',np.round(s.state()['object_pos'],3))
print('under end',s.state()['object_pos'])
for n in ['index_DP','middle_DP','ring_DP','pinky_DP']:print(n,np.round(D.xpos[M.body('palmleft_'+n).id],3))
for i,c in enumerate(D.contact[:D.ncon]):
 b1=M.body(M.geom_bodyid[c.geom1]).name;b2=M.body(M.geom_bodyid[c.geom2]).name
 if 'object' in b1 or 'object' in b2:
  f=np.zeros(6);mujoco.mj_contactForce(M,D,i,f);print('contact',b1,b2,'pos',np.round(c.pos,3),'dist',round(c.dist,4),'n',np.round(c.frame[:3],2),'f',np.round(f[:3],1))
# lift while holding
phigh=p_under+np.array([0,0,.05]);qh=ik(phigh,R0,qu);H=U.copy();H[:7]=qh
for k in range(160):
 s.step(U+(H-U)*(k+1)/160)
 if (k+1)%40==0:print('lift',k+1,'palm',np.round(s.state()['palm_pos'],3),'obj',np.round(s.state()['object_pos'],3),'dist',s.goal_distance())
for _ in range(60):s.step(H)
print('end',s.progress())
